// Confirms the incoming item is a well-formed Report Contract
// (docs/contracts/report-contract.md) before any renderer logic runs.
// This is the only node that validates the contract's envelope shape -
// every node after it trusts this completely.
const STAGE = 'excel_writer';
const WORKFLOW_VERSION = '1.0';
const VALID_STATUSES = ['PASS', 'FAIL', 'BLOCKED', 'MANUAL_REVIEW'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (Documentation Agent, or anything
// earlier) are not Report Contracts and must not be re-validated as
// one - pass them through unchanged, same convention as every prior
// workflow.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = ['workflow_version', 'report_version', 'test_case', 'decision', 'report'];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    `Report Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields }
  ) };
}

if (typeof item.test_case !== 'object' || item.test_case === null || Array.isArray(item.test_case) ||
    typeof item.test_case.test_id !== 'string' || item.test_case.test_id.trim() === '') {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract test_case must be an object with a non-empty test_id',
    {}
  ) };
}

const r = item.report;
if (typeof r !== 'object' || r === null || Array.isArray(r) ||
    !VALID_STATUSES.includes(r.status) ||
    typeof r.actual_result !== 'string' ||
    typeof r.reasoning !== 'string' ||
    typeof r.tester_notes !== 'string' ||
    typeof r.confidence !== 'number' || r.confidence < 0 || r.confidence > 1 ||
    typeof r.decision_basis !== 'string' ||
    typeof r.manual_review !== 'boolean' ||
    typeof r.evidence_summary !== 'string' ||
    typeof r.execution_time !== 'string') {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract report object is missing or has an invalid status/actual_result/reasoning/tester_notes/confidence/decision_basis/manual_review/evidence_summary/execution_time',
    { test_id: item.test_case.test_id }
  ) };
}

return { json: item };

// Excel Adapter - Report Contract stage of the renderer pattern (see
// Architecture Note sticky). The only node in this workflow that reads
// `report.*` / `test_case.*` field names directly - everything after
// this node only ever sees the canonical, renderer-agnostic field names
// below. This is what a future Sheets/PDF adapter would reproduce
// unchanged; only 'Apply Column Map' and everything after it differs
// per renderer.
//
// Every value here is either carried straight through or a direct
// rename - never invented, never re-derived. 'notes' maps to
// report.reasoning (the AI/deterministic explanation of the verdict -
// the original Excel MCP schema's 'Notes' column per
// docs/architecture/milestone-1.md section 4/6), kept distinct from
// 'tester_notes' (report.tester_notes - the fixed per-status action
// guidance a human tester reads).
const item = $input.item.json;
const report = item.report;
const testCase = item.test_case;

return { json: {
  test_id: testCase.test_id,
  fields: {
    status: report.status,
    actual_result: report.actual_result,
    notes: report.reasoning,
    tester_notes: report.tester_notes,
    confidence: report.confidence,
    decision_basis: report.decision_basis,
    manual_review: report.manual_review,
    execution_date: report.execution_time,
    evidence_summary: report.evidence_summary
  }
} };

// Apply Column Map - COLUMN_MAP stage of the renderer pattern (see
// Architecture Note sticky). The single source of truth for this
// renderer's real Excel column headers, defined once, here - per
// docs/workflow-standards.md's column-mapping rule, no other node in
// this workflow references a raw header string. Renderer-owned columns
// only: Test ID is the lookup key, never part of __updates, so it can
// never be overwritten downstream (satisfies 'never update Test ID,
// Description, Steps, Expected Result' - those simply never appear in
// this map at all).
const COLUMN_MAP = {
  test_id: 'Test ID',
  status: 'Status',
  actual_result: 'Actual Result',
  notes: 'Notes',
  tester_notes: 'Tester Notes',
  confidence: 'Confidence',
  decision_basis: 'Decision Basis',
  manual_review: 'Manual Review',
  execution_date: 'Execution Date',
  evidence_summary: 'Evidence Summary'
};

const adapterOutput = $input.item.json;

const updates = {};
for (const [canonicalKey, header] of Object.entries(COLUMN_MAP)) {
  if (canonicalKey === 'test_id') continue;
  updates[header] = adapterOutput.fields[canonicalKey];
}

return { json: {
  __lookup_header: COLUMN_MAP.test_id,
  __lookup_value: adapterOutput.test_id,
  __updates: updates
} };

// Handles 'Read Workbook File''s error output (file missing, locked, or
// otherwise unreadable - docs/architecture/milestone-1.md section 4's
// documented Excel MCP failure mode). Deliberately a single generic
// code, not a classifier - same 'no retry, no classification' rule as
// every prior workflow's native-node error handling.
const STAGE = 'excel_writer';
const WORKFLOW_VERSION = '1.0';
const REPORT_FILE_PATH = '/data/reports/qa-report.xlsx';

const mapping = $('Apply Column Map').first().json;
const rawError = $input.item.json;
const message = String(rawError.error || rawError.message || JSON.stringify(rawError));

return { json: {
  status: 'ERROR',
  stage: STAGE,
  code: 'REPORT_FILE_UNAVAILABLE',
  message: `Could not read the report workbook at "${REPORT_FILE_PATH}": ${message}`,
  details: { file_path: REPORT_FILE_PATH, test_id: mapping.__lookup_value },
  timestamp: new Date().toISOString(),
  workflow_version: WORKFLOW_VERSION
} };

// Locate & Merge Row - the renderer's read-modify-write core. Finds the
// one workbook row whose lookup column matches this Report Contract's
// test_id, and overlays ONLY 'Apply Column Map''s __updates onto that
// row - every other key already on the row object (Test ID,
// Description, Steps, Expected Result, and any other column this
// workbook happens to have) is preserved by the object spread below,
// untouched, because __updates structurally never contains those keys.
// Every non-matching row is returned completely unchanged. This node
// makes no judgment about the verdict - it only locates and merges data
// that 'Excel Adapter'/'Apply Column Map' already finalized.
const mapping = $('Apply Column Map').first().json;
const rows = $input.all().map((i) => i.json);

let matchedIndex = -1;
for (let i = 0; i < rows.length; i++) {
  if (String(rows[i][mapping.__lookup_header]) === String(mapping.__lookup_value)) {
    matchedIndex = i;
    break;
  }
}

if (matchedIndex === -1) {
  return [{ json: { __status: 'NOT_FOUND', test_id: mapping.__lookup_value } }];
}

const updatedRows = rows.map((row, i) => (i === matchedIndex ? { ...row, ...mapping.__updates } : row));

return [{ json: { __status: 'MATCHED', test_id: mapping.__lookup_value, rows: updatedRows } }];

// The Report Contract's test_id has no matching row in the workbook -
// this workflow only updates an existing row (per Task 5.1's brief), it
// never appends one. Surfaced loudly rather than silently skipped or
// silently appended, same 'fail loudly' rule as every prior workflow.
const STAGE = 'excel_writer';
const WORKFLOW_VERSION = '1.0';

const item = $input.item.json;

return { json: {
  status: 'ERROR',
  stage: STAGE,
  code: 'TARGET_ROW_NOT_FOUND',
  message: `No row found in the report workbook for Test ID "${item.test_id}"`,
  details: { test_id: item.test_id },
  timestamp: new Date().toISOString(),
  workflow_version: WORKFLOW_VERSION
} };

// Turns the single { rows: [...] } item 'Locate & Merge Row' produced
// back into one n8n item per row, the shape 'Write Workbook Rows'
// (spreadsheetFile, operation 'toFile') needs to render every row -
// unchanged and updated alike - back into the workbook.
const item = $input.first().json;
return item.rows.map((row) => ({ json: row }));

// Handles 'Write Workbook File''s error output (file locked, disk full,
// permissions) - docs/architecture/milestone-1.md section 4's other
// documented Excel MCP failure mode. Same 'no retry, no classification'
// rule as every other native-node error handler in this workflow.
const STAGE = 'excel_writer';
const WORKFLOW_VERSION = '1.0';
const REPORT_FILE_PATH = '/data/reports/qa-report.xlsx';

const mapping = $('Apply Column Map').first().json;
const rawError = $input.item.json;
const message = String(rawError.error || rawError.message || JSON.stringify(rawError));

return { json: {
  status: 'ERROR',
  stage: STAGE,
  code: 'WORKBOOK_WRITE_FAILED',
  message: `Could not write the report workbook at "${REPORT_FILE_PATH}": ${message}`,
  details: { file_path: REPORT_FILE_PATH, test_id: mapping.__lookup_value },
  timestamp: new Date().toISOString(),
  workflow_version: WORKFLOW_VERSION
} };

// A deterministic confirmation object for this run - not a new
// contract, just a record of what this renderer actually wrote, for
// logging/auditing. Nothing here is invented: columns_updated is read
// directly from the same __updates object that was written to the
// workbook.
const REPORT_FILE_PATH = '/data/reports/qa-report.xlsx';
const mapping = $('Apply Column Map').first().json;

return { json: {
  status: 'WRITTEN',
  test_id: mapping.__lookup_value,
  file_path: REPORT_FILE_PATH,
  columns_updated: Object.keys(mapping.__updates),
  written_at: new Date().toISOString()
} };
